1	import React, { useEffect, useRef } from 'react';
2	import {
3	  Box,
4	  Center,
5	  Drawer,
6	  DrawerBody,
7	  DrawerContent,
8	  DrawerOverlay,
9	  Image,
10	  Spinner,
11	  Text,
12	  useMultiStyleConfig,
13	} from '@salesforce/retail-react-app/app/components/shared/ui';
14	import { useCustomerType } from '@salesforce/commerce-sdk-react';
15	import { noop } from '@salesforce/retail-react-app/app/utils/utils';
16	import { DRAWER_BODY_SX, DRAWER_CONTENT_SX, DRAWER_OVERLAY_SX } from './drawer-menu.css';
17	import { ZimmNavItem } from 'app/components/ui-kits/atoms/zimmNavItem';
18	import { useUiCopy } from 'app/hooks/useUiCopy';
19	import { useHeaderNav } from 'app/hooks/useHeaderNav';
20	import { useDrawerMenuState } from 'app/hooks/useDrawerMenuState';
21	import { resolveImageEntry } from 'app/utils/resolveImageEntry';
22	import type { HeaderNavItemEntry, NavGroupEntry } from 'app/types/contentful';
23	
24	const SIGN_IN_HREF = '/login';
25	const WISHLIST_HREF = '/account/wishlist';
26	const ACCOUNT_HREF = '/account';
27	
28	// A two-column item's first link per group is styled like a heading while staying a real
29	// clickable ZimmNavItem (see megaMenuContent/index.tsx's PRIMARY_LEAF_LINK_SX for the
30	// desktop/tablet equivalent). marginBottom tops l2LinkList's 12px gap up to Figma's 24px for
31	// this one pair, rather than changing the list's gap for every item.
32	const L2_PRIMARY_LINK_SX = {
33	  textStyle: 'heading1Strong',
34	  marginBottom: 'var(--zimm-scale-s)',
35	};
36	const L2_LEAF_LINK_SX = { textStyle: 'heading3' };
37	
38	type DrawerMenuViewProps = {
39	  isOpen: boolean;
40	  onClose: () => void;
41	  onLogoClick?: () => void;
42	  /** Region-resolved header nav items, or undefined while loading (see useHeaderNav.ts). */
43	  items: ReadonlyArray<HeaderNavItemEntry> | undefined;
44	  isLoading: boolean;
45	  /** The L1 item currently drilled into — renders the L2 panel when set. */
46	  activeItem: HeaderNavItemEntry | null;
47	  isDrilledIn: boolean;
48	  /** Called when the shopper taps an L1 row that has columns. */
49	  onDrillInto: (item: HeaderNavItemEntry) => void;
50	};
51	
52	/** L1 root nav list — a direct-link item renders as a ZimmNavItem link; an item with columns
53	 *  renders as a button that drills to L2. No chevron — Figma renders every row as plain text. */
54	const DrawerMenuL1Nav = ({
55	  items,
56	  onDrillInto,
57	  styles,
58	}: {
59	  items: ReadonlyArray<HeaderNavItemEntry>;
60	  onDrillInto: (item: HeaderNavItemEntry) => void;
61	  styles: Record<string, Record<string, unknown>>;
62	}) => (
63	  <Box as="ul" {...styles.l1List} listStyleType="none">
64	    {items.map((item) => {
65	      const { label, href, columns = [] } = item.fields;
66	      const hasColumns = columns.length > 0;
67	
68	      return (
69	        <Box as="li" key={item.sys.id} {...styles.l1Row}>
70	          {hasColumns ? (
71	            <ZimmNavItem label={label} onClick={() => onDrillInto(item)} sx={{ textStyle: 'heading1Strong' }} />
72	          ) : (
73	            <ZimmNavItem label={label} href={href} sx={{ textStyle: 'heading1Strong' }} />
74	          )}
75	        </Box>
76	      );
77	    })}
78	  </Box>
79	);
